/**
 * The vendored engine and data are Agent_Loop_Sim's files at the pinned commit, byte for byte;
 * the data files match the engine's manifest; and the site's fixtures were generated by the
 * Python reference at that same commit.
 */
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";

import { describe, expect, it } from "vitest";

import VENDORED from "@/lib/engine/vendor/VENDORED.json";

const ROOT = join(__dirname, "../..");
const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");

describe("vendored engine", () => {
  it("every file matches the SHA-256 recorded with its commit", () => {
    const files = Object.entries(VENDORED.files);
    expect(files.length).toBeGreaterThanOrEqual(40);
    expect(VENDORED.commit).toMatch(/^[0-9a-f]{40}$/);
    for (const [path, rec] of files)
      expect(sha(readFileSync(join(ROOT, path))), path).toBe(rec.sha256);
  });

  it("vendors the TS port with its orchestration module, its fixtures and the LangGraph recording", () => {
    const froms = Object.values(VENDORED.files).map((f) => f.from);
    for (const f of [
      "ts/src/orchestration/graph.ts",
      "ts/src/orchestration/durable.ts",
      "ts/src/orchestration/views.ts",
      "ts/src/orchestration/index.ts",
      "ts/src/orchestration_data.json",
      "ts/src/rng.ts",
      "fixtures/orchestration_fixtures.json",
      "fixtures/orchestration_results.md",
      "fixtures/langgraph_recordings.json",
      "conformance/langgraph_graphs.py",
      "fixtures/orchestration2_fixtures.json",
      "fixtures/orchestration2_results.md",
    ])
      expect(froms).toContain(f);
  });

  it("the engine's own orchestration fixtures are reproduced by the vendored port", async () => {
    const { O } = await import("@/lib/engine");
    const fx = JSON.parse(
      readFileSync(
        join(ROOT, "tests/fixtures/orchestration_fixtures.json"),
        "utf8",
      ),
    ) as Record<string, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
    expect(fx.engine).toBe("1.11.1");
    for (const s of fx.sessions)
      expect(O.runSession(O.graph(s.graph), O.session(s.name).ops).ops).toEqual(
        s.ops,
      );
    for (const [n, r] of Object.entries(fx.durable))
      expect(O.runDurable(O.durableScenario(n).params)).toEqual(r);
    for (const s of fx.sweeps.slice(0, 4))
      expect(O.chargeSweep(s.q, s.attempts, s.runs, s.seed)).toEqual(s);
  });

  it("the engine's part-2 fixtures (patterns, DES, reliability) are reproduced by the vendored port", async () => {
    const { O } = await import("@/lib/engine");
    const fx = JSON.parse(
      readFileSync(
        join(ROOT, "tests/fixtures/orchestration2_fixtures.json"),
        "utf8",
      ),
    ) as Record<string, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
    expect(fx.engine).toBe("1.11.1");
    for (const n of O.patterns.PATTERNS) {
      expect(O.patterns.plan(n)).toEqual(fx.plans[n]);
      expect(O.patterns.patternFrames(O.patterns.plan(n))).toEqual(
        fx.frames[n],
      );
      expect(
        O.des.simulate(O.patterns.plan(n), {
          workflows: 5,
          per_min: 4.0,
          trace: true,
          samples: 20,
          seed: 5,
        }),
      ).toEqual(fx.small[n]);
    }
    expect(O.patterns.compare()).toEqual(fx.compare);
    expect(
      O.study.relStudy(O.study.REL.e, O.study.REL.w, O.study.REL_CONFIGS[2]!),
    ).toEqual(fx.rel[2]);
  });

  it("the vendored port equals the committed LangGraph recording", async () => {
    const { O } = await import("@/lib/engine");
    const rec = JSON.parse(
      readFileSync(join(ROOT, "src/data/langgraph_recordings.json"), "utf8"),
    ) as Record<string, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
    expect(rec.langgraph).toBe("1.2.14");
    for (const s of rec.sessions) {
      const g = O.graph(s.graph);
      const r = O.runSession(g, O.session(s.name).ops);
      r.ops.forEach((o: Record<string, any>, i: number) => {
        // eslint-disable-line @typescript-eslint/no-explicit-any
        expect(O.outcome(o.result)).toEqual(s.ops[i].outcome);
        expect(O.comparableHistory(g, o.history)).toEqual(s.ops[i].history);
      });
    }
  });

  it("the site's fixtures come from the same commit", () => {
    const fx = JSON.parse(
      readFileSync(join(ROOT, "tests/fixtures/site_fixtures.json"), "utf8"),
    ) as { commit: string };
    expect(fx.commit).toBe(VENDORED.commit);
  });
});
